 a1:'assets/lab_run_004/lot_change_initial_001.png',a2:'assets/lab_run_004/verification_plan_001.png',a3:'assets/lab_run_004/reference_material_targets_001.png',a4:'assets/lab_run_004/run_qc_lot_comparison_001.png',a5:'assets/lab_run_004/variant_concordance_001.png',a6:'assets/lab_run_004/lot_release_checklist_001.png',a7:'assets/lab_run_004/change_control_closeout_001.png'
